# ---- 第 6 车道资格门槛（静默）----
EXCLUDE = {"node_modules", ".git", "dist", "build", "vendor", ".next",
           "__pycache__", ".venv", "target", "coverage", "third_party"}
SRC_EXT = {".py",".js",".mjs",".cjs",".ts",".tsx",".jsx",".go",".rs",".java",
           ".c",".h",".cpp",".cc",".hpp",".rb",".php",".swift",".kt",".cs",
           ".sh",".vue",".svelte",".scala",".clj",".ex",".exs",".erl",".hs",
           ".lua",".dart"}

def count_sources(d):
    files = lines = 0
    try:
        names = os.listdir(d)
    except OSError:
        return 0, 0
    for name in names:
        p = os.path.join(d, name)
        if not os.path.isfile(p):
            continue
        if os.path.splitext(name)[1].lower() in SRC_EXT:
            files += 1
            try:
                with open(p, "r", errors="ignore") as f:
                    lines += sum(1 for _ in f)
            except OSError:
                pass
    return files, lines

gate = {"eligible": False, "reason": None}
if rc == 0 and top:
    root = top
    candidates = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in EXCLUDE]
        rel = os.path.relpath(dirpath, root)
        depth = 0 if rel == "." else rel.count(os.sep) + 1
        if depth > 3:
            dirnames[:] = []
            continue
        files, lines = count_sources(dirpath)
        if files >= 8 or lines >= 500:
            candidates.append("." if rel == "." else rel)
    gate["candidates"] = candidates
    if not candidates:
        gate["reason"] = "no candidate dirs"
    else:
        def covered(rel):
            parts = [] if rel == "." else rel.split(os.sep)
            for i in range(len(parts), -1, -1):
                anc = root if i == 0 else os.path.join(root, *parts[:i])
                if os.path.exists(os.path.join(anc, "AGENTS.md")):
                    return True
            return False
        unc = [c for c in candidates if not covered(c)]
        ratio = len(unc) / len(candidates)
        gate["missing_ratio"] = round(ratio, 3)
        gate["uncovered"] = unc
        if ratio < 0.5:
            gate["reason"] = f"missing ratio {ratio:.2f} < 0.5"
        else:
            gate["eligible"] = True
else:
    gate["reason"] = "not a git repo"
out["gate6"] = gate

print(json.dumps(out, ensure_ascii=False, indent=1))
